python3 << 'EOF'
import pandas as pd

files = {
    '2015-2016': '/tmp/1516_ratings.xls',
    '2016-2017': '/tmp/1617_ratings.xls',
    '2017-2018': '/tmp/1718_ratings.xlsx',
    '2018-2019': '/tmp/1819_ratings.xlsx',
}

for year, path in files.items():
    print(f"\n=== {year} ===")
    try:
        df = pd.read_excel(path)
        print(f"Shape: {df.shape}")
        print(f"Columns: {list(df.columns)}")
        # Find Vinton County High School
        mask = df.apply(lambda row: row.astype(str).str.contains('Vinton County High', case=False).any(), axis=1)
        matches = df[mask]
        if len(matches) > 0:
            print(f"Found {len(matches)} matches")
            for _, row in matches.iterrows():
                print(row.to_dict())
        else:
            print("No matches found")
            # Try searching for "Vinton"
            mask2 = df.apply(lambda row: row.astype(str).str.contains('Vinton', case=False).any(), axis=1)
            matches2 = df[mask2]
            if len(matches2) > 0:
                print(f"Found {len(matches2)} Vinton matches:")
                for _, row in matches2.iterrows():
                    print(row.to_dict())
    except Exception as e:
        print(f"Error: {e}")
EOF

